import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';const ch=createRequire('/opt/news-flow/current/package.json')('cheerio'),r=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-recover25-20261122/cnn-final-failures.json')),p=r.rows.find(p=>p.url.includes('iowa-chemicals')),clean=s=>String(s||'').normalize('NFC').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim(),$=ch.load(gunzipSync(fs.readFileSync(p.file)).toString());const graph=JSON.parse($('script[type="application/ld+json"]').first().text()),a=(Array.isArray(graph)?graph:[graph]).find(a=>a.articleBody),schema=clean(a.articleBody),paras=$('article.article--lite p.paragraph--lite').toArray().map(e=>clean($(e).text())).filter(Boolean),gaps=[],missing=[];let cursor=0,matched=0;for(const text of paras){const i=schema.indexOf(text,cursor);if(i<0)missing.push(text.slice(0,120));else{if(i>cursor)gaps.push(schema.slice(cursor,i).trim());matched+=text.length;cursor=i+text.length;}}if(cursor<schema.length)gaps.push(schema.slice(cursor));console.log(JSON.stringify({url:p.url,headings:$('article.article--lite').find('h1,h2,h3,h4,h5,h6').toArray().map(e=>({tag:e.name,class:$(e).attr('class'),text:clean($(e).text())})),schemaChars:schema.length,visibleChars:paras.join(' ').length,coverage:matched/schema.length,missing,gaps:gaps.filter(Boolean),schemaStart:schema.slice(0,200),visibleStart:paras[0],bodyOtherText:$('article.article--lite').text().replace(/\s+/g,' ').trim().slice(-400)}));
